def get_nd4j_dtype(np_dtype):
    """
    Gets the equivalent nd4j data type
    for a given numpy data type.
    # Arguments
        np_dtype: Numpy data type. One of
            ['float64', 'float32', 'float16']
    """
    if np_dtype == 'float64':
        return 'DOUBLE'
    elif np_dtype == 'float32':
        return 'FLOAT'
    elif np_dtype == 'float16':
        return 'HALF'
    else:
        raise TypeError('Invalid numpy data type:', np_dtype)

